from jsonb_to_recordset($json$[{"id":"che-pe-101","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Dobereiner arranged chemically similar elements into sets of three that he called","options":["octaves","triads","periods","blocks"],"answer_index":1,"explanation":"Each Dobereiner triad contains three related elements, with the middle one intermediate in properties.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-102","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In a Dobereiner triad the atomic mass of the middle element is approximately","options":["the product of the other two atomic masses","the arithmetic mean of the other two atomic masses","twice the atomic mass of the lightest member","equal to the atomic number of the heaviest member"],"answer_index":1,"explanation":"The middle atomic mass is close to the average of the first and third members.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-103","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Newlands noticed that every eighth element resembled the first and named this regularity the","options":["law of octaves","law of triads","modern periodic law","octet rule of Lewis"],"answer_index":0,"explanation":"He compared the repeating chemical likeness to the octaves of a musical scale.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-104","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Newlands' arrangement gave a useful resemblance of properties only as far as the element","options":["helium","calcium","iron","iodine"],"answer_index":1,"explanation":"Beyond calcium the octave pattern broke down as many new elements were fitted in.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-105","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Mendeleev's periodic law stated that the properties of elements are a periodic function of their","options":["atomic numbers","atomic masses","mass numbers only","neutron counts"],"answer_index":1,"explanation":"Mendeleev ordered the then-known elements by increasing atomic mass and found a repeating pattern.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-106","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A distinctive feature of Mendeleev's table was that he","options":["placed isotopes in separate groups","left vacant places for elements still undiscovered","arranged elements strictly by atomic number","refused to predict any new element"],"answer_index":1,"explanation":"Gaps such as those for eka-aluminium and eka-silicon were later filled by gallium and germanium.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-107","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A recognised limitation of Mendeleev's classification is the uncertain position of","options":["alkali metals","isotopes of the same element","halogens","alkaline earth metals"],"answer_index":1,"explanation":"Isotopes have different atomic masses but identical chemistry, so a mass-based table cannot place them uniquely.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-108","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The element Mendeleev called eka-aluminium was later isolated and named","options":["scandium","gallium","germanium","silicon"],"answer_index":1,"explanation":"Eka-aluminium occupies the place under aluminium and matches gallium in properties and atomic mass.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-109","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Eka-silicon of Mendeleev's table corresponds to the later-discovered element","options":["tin","lead","germanium","carbon"],"answer_index":2,"explanation":"Germanium fills the gap Mendeleev left beneath silicon and agrees with his predicted properties.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-110","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Tellurium was placed before iodine in Mendeleev's table even though Te has the greater atomic mass so that","options":["tellurium would sit with the noble gases","chemically similar elements remained in the same group","iodine would have a lower atomic number","the table would contain only eight periods"],"answer_index":1,"explanation":"Chemical analogy (Te with O, S, Se; I with F, Cl, Br) was given priority over a strict mass sequence.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-111","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the triad lithium–sodium–potassium the atomic mass of sodium is close to","options":["the difference of the atomic masses of Li and K","the mean of the atomic masses of lithium and potassium","twice the atomic mass of potassium","the atomic number of lithium"],"answer_index":1,"explanation":"Li (7), Na (23) and K (39) illustrate Dobereiner's mean-mass rule for a triad.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-112","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Argon (atomic mass about 40) sits before potassium (about 39) in the older table because","options":["argon has the smaller atomic number, which Mendeleev already used","chemical properties forced the placement; atomic number later justified it","potassium is a noble gas","argon has fewer neutrons than potassium"],"answer_index":1,"explanation":"Mass inversion of the Ar–K pair is an anomalous pair of Mendeleev's table, resolved by Moseley's atomic-number order.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-113","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The modern periodic law states that properties of elements are a periodic function of their","options":["atomic masses","atomic numbers","mass numbers","neutron-to-proton ratios"],"answer_index":1,"explanation":"After Moseley, atomic number Z replaced atomic mass as the classifying index.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-114","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Henry Moseley's X-ray studies showed that the correct basis for classifying elements is","options":["atomic mass","atomic number","density","atomic volume"],"answer_index":1,"explanation":"The frequency of characteristic X-rays varies regularly with Z, not with A.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-115","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The long form of the periodic table is constructed primarily on the basis of","options":["atomic volumes of Lothar Meyer","electronic configurations of the elements","boiling points only","natural abundances"],"answer_index":1,"explanation":"Each period begins when a new principal shell starts to fill and ends at a noble-gas configuration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-116","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the long form of the periodic table the number of vertical groups is","options":["seven","eight","sixteen","eighteen"],"answer_index":3,"explanation":"IUPAC numbers the groups from 1 to 18 in the 18-column table.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-117","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The long form of the periodic table contains how many horizontal periods?","options":["five","six","seven","eighteen"],"answer_index":2,"explanation":"Periods 1 to 7 run from hydrogen to the heaviest known elements.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-118","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A horizontal row of the periodic table is called a","options":["group","period","block","family of isotopes"],"answer_index":1,"explanation":"Elements in one period have the same valence principal quantum number.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-119","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A vertical column of the periodic table is called a","options":["period","group","series of isobars","shell"],"answer_index":1,"explanation":"A group collects elements with the same valence-shell configuration and similar chemistry.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-120","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Elements of one group show similar chemical properties mainly because they have","options":["the same mass number","the same valence-shell electronic configuration","identical atomic radii","the same number of neutrons"],"answer_index":1,"explanation":"Valence configuration repeats down a group (for example ns¹ for alkali metals).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-121","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The period number of an element equals the","options":["number of valence electrons","principal quantum number of its valence shell","atomic number divided by two","group number in every case"],"answer_index":1,"explanation":"Period 3 elements have n = 3 as the outer shell, period 4 have n = 4, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-122","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"IUPAC temporary names for elements with Z greater than 100 are built from","options":["the discoverer's surname only","Latin roots of the digits of the atomic number","the atomic mass rounded to an integer","the name of the mineral in which they occur"],"answer_index":1,"explanation":"Each digit 0–9 has a Latin stem (nil, un, bi, …) so Z = 107 is unnilseptium until a permanent name is approved.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-123","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Isotopes of one element occupy a single position in the modern table because they share the","options":["mass number","atomic number","neutron number","atomic mass exactly"],"answer_index":1,"explanation":"The modern law uses Z; isotopes differ in N and A but not in Z or chemistry.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-124","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The argon–potassium pair is placed in the order Ar then K once elements are arranged by","options":["atomic mass","atomic number","density","atomic volume"],"answer_index":1,"explanation":"Z(Ar) = 18 and Z(K) = 19, so the modern sequence matches chemical groups even though A(Ar) > A(K).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-125","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A group-2 (alkaline earth) atom has how many valence electrons in the ns subshell?","options":["one","two","three","eight"],"answer_index":1,"explanation":"The configuration ends in ns², so the group number in the s-block equals the valence-electron count.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"modern-law-table","appear_count":0,"years":[],